  const c = Object.assign({}, DEFAULT, config || {});
  document.getElementById('webhook').value = c.webhook || '';
  document.getElementById('interval').value = c.intervalMinutes || 15;
  document.getElementById('enabled').checked = c.enabled !== false;
}

